p('resume','RES04','Use present tense for ongoing work and past tense for completed contributions.',['S04'],check='Tense is compatible with event timing.',exceptions=['A completed accomplishment in a current job can use past tense.'])
p('resume','RES05','Resume length depends on experience, purpose and explicit application instructions.',['S05','S06','S26'],default='Concise one page for many early-career cases; allow two pages when relevant experience warrants it.',check='Length preference and destination constraints preserved.',exceptions=['Academic CVs differ; current US federal instructions cap resumes at two pages.'])
