p('resume','RES07','Preserve exact employment, education, credentials and chronology; tailoring changes emphasis rather than history.',['S16'],scope='universal_product_rule',kind='research_informed_product_rule',check='Structured facts and evidence match every emitted identity/date/credential.')
p('resume','RES08','Avoid first-person pronouns and generic responsibilities when specific contributions are available.',['S03'],default='Concise action-led bullets.',check='Soft writing review; natural valid variation is allowed.')
p('resume','RES09','Check the whole document for repeated achievements and consistent terminology.',['S05','S10'],kind='research_informed_product_rule',check='Same-event repetition is justified or removed across sections.')
p('resume','RES10','Keep sensitive personal attributes off a typical US industry resume unless the user specifically requires appropriate inclusion.',['S03'],check='No inferred age, health, religion, family status or demographic facts.',exceptions=['Geographic conventions and legitimate application instructions differ; route uncertain cases to user review.'])
